declare(strict_types=1);require __DIR__.'/../lib/core.php';if(PHP_SAPI!=='cli'){http_response_code(403);exit("CLI only\n");}$db=x1_db();if(!$db){fwrite(STDERR,"PDO SQLite required\n");exit(2);}foreach(glob(X1_ROOT.'/data/*.json')?:[]as $f){$name=basename($f,'.json');$v=json_decode((string)file_get_contents($f),true);if(!is_array($v))continue;x1_write($name,$v);echo"imported ".$name."\n";}if((int)x1_db_scalar('SELECT COUNT(*) FROM users',[],0)===0){foreach(x1_read('admins')as $a){if(empty($a['username'])||empty($a['password']))continue;$now=date('c');x1_db_exec('INSERT OR IGNORE INTO users(id,username,password_hash,role,enabled,created_at,updated_at) VALUES(?,?,?,?,?,?,?)',[(string)($a['id']??x1_id()),(string)$a['username'],(string)$a['password'],(string)($a['role']??'owner'),1,(string)($a['created_at']??$now),$now]);}}echo"migration complete\n";